// if(M.isContinuous())
// {
// cols *= rows;
// rows = 1;
// }
// for(int i = 0; i < rows; i++)
// {
// const double* Mi = M.ptr<double>(i);
// for(int j = 0; j < cols; j++)
// sum += std::max(Mi[j], 0.);
// }
// @endcode
